class Solution:
    def permute(self, nums: List[int]) -> List[List[int]]:
        out, cur, used = [], [], [False] * len(nums)
        def build():
            if len(cur) == len(nums):
                out.append(cur[:])
                return
            for i, x in enumerate(nums):
                if not used[i]:
                    used[i] = True
                    cur.append(x)
                    build()
                    cur.pop()
                    used[i] = False
        build()
        return out

