            for (int i = 0; i < 2 * n && balance >= 0; i++) {
                boolean open = (mask >> i & 1) == 1;
                sb.append(open ? '(' : ')');
                balance += open ? 1 : -1;
            }
            if (balance == 0 && sb.length() == 2 * n) out.add(sb.toString());
        }
        return out;
    }
}

