    def makesquare(self, matchsticks: List[int]) -> bool:
        total = sum(matchsticks)
        if total % 4:
            return False
        side, sides = total // 4, [0] * 4
        def place(i):
            if i == len(matchsticks):
                return sides[0] == sides[1] == sides[2] == side
            for k in range(4):
                if sides[k] + matchsticks[i] <= side:
                    sides[k] += matchsticks[i]
                    if place(i + 1):
                        return True
                    sides[k] -= matchsticks[i]
