        if (i == s.length) return true;
        for (int k = 0; k < 4; k++) {
            if (sides[k] + s[i] > side) continue;
            if (k > 0 && sides[k] == sides[k - 1]) continue;
            sides[k] += s[i];
            if (place(s, i + 1, sides, side)) return true;
            sides[k] -= s[i];
        }
        return false;
    }
}

