class Solution {
    public int totalNQueens(int n) { return place(new int[n], 0); }
    private int place(int[] col, int r) {
        int n = col.length;
        if (r == n) return 1;
        int total = 0;
        for (int c = 0; c < n; c++) {
            boolean ok = true;
            for (int i = 0; i < r && ok; i++) if (col[i] == c || Math.abs(col[i] - c) == r - i) ok = false;
            if (!ok) continue;
            col[r] = c;
            total += place(col, r + 1);
        }
        return total;
    }
}

