            if (cols[c] || d1[r - c + n - 1] || d2[r + c]) continue;
            cols[c] = d1[r - c + n - 1] = d2[r + c] = true;
            total += place(n, r + 1, cols, d1, d2);
            cols[c] = d1[r - c + n - 1] = d2[r + c] = false;
        }
        return total;
    }
