class Solution {
    public int totalNQueens(int n) { return count(n, 0, 0, 0, 0); }
    private int count(int n, int row, int cols, int d1, int d2) {
        if (row == n) return 1;
        int total = 0, free = ~(cols | d1 | d2) & ((1 << n) - 1);
        while (free != 0) {
            int bit = free & -free;
            free -= bit;
            total += count(n, row + 1, cols | bit, (d1 | bit) << 1, (d2 | bit) >> 1);
        }
        return total;
    }
}

