class Solution:
    def wordBreak(self, s: str, wordDict: List[str]) -> List[str]:
        words = set(wordDict)
        @lru_cache(maxsize=None)
        def go(i):
            if i == len(s):
                return [""]
            out = []
            for j in range(i + 1, len(s) + 1):
                w = s[i:j]
                if w in words:
                    out += [w if not rest else w + " " + rest for rest in go(j)]
            return out
        return go(0)

